target.css:
:root {
  --ink: #183f3d;
  --leaf: #2f7665;
  --mist: #e2f1e9;
  --paper: #fffef8;
  --line: #bad9cd;
}

.rain-card {
  box-sizing: border-box;
  width: 470px;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-mark {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  background: var(--leaf);
  border-radius: 14px;
  color: var(--paper);
  font-size: 15px;
  font-weight: 800;
}

.card-copy {
  flex: 1;
}

.card-copy p,
.card-copy h1 {
  margin: 0;
}

.eyebrow {
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.card-copy h1 {
  color: var(--ink);
  font-size: 19px;
  line-height: 1.25;
}

.details {
  color: var(--ink);
  font-size: 13px;
}

.status {
  padding: 6px 9px;
  background: var(--mist);
  border-radius: 999px;
  color: var(--leaf);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
}
